package com.portfolio.agent.answer.runtime;
import org.junit.jupiter.api.Test; import java.time.Duration; import java.util.Map; import static org.assertj.core.api.Assertions.*;
class ModelOperationPolicyTest { @Test void allOperationsDefaultDisabled(){assertThat(ModelOperationPolicyRegistry.defaults().asMap()).allSatisfy((op,p)->assertThat(p.getMode()).isEqualTo(OperationMode.DISABLED));} @Test void enabledIncompleteOperationFailsStartup(){assertThatThrownBy(()->new ModelOperationPolicyRegistry(Map.of(ModelOperation.GENERAL_ANSWER_MATERIAL,new ModelOperationPolicy(ModelOperation.GENERAL_ANSWER_MATERIAL,OperationMode.ENABLED,"provider",null,Duration.ofSeconds(1))))).isInstanceOf(IllegalStateException.class);} @Test void operationsAreIndependent(){ModelOperationPolicy p=new ModelOperationPolicy(ModelOperation.GENERAL_ANSWER_MATERIAL,OperationMode.ENABLED,"provider","schema-v1",Duration.ofSeconds(1));assertThat(p.readiness()).isEqualTo(OperationReadiness.AVAILABLE_WITH_DETERMINISTIC_FALLBACK);assertThat(ModelOperationPolicyRegistry.defaults().get(ModelOperation.CROSS_DOMAIN_EXPRESSION).getMode()).isEqualTo(OperationMode.DISABLED);} }
